import { createClient } from '@deepgram/sdk';
import { readFileSync } from 'fs';

const deepgram = createClient(process.env.DEEPGRAM_API_KEY!);

// Transcribe from a URL
const { result, error } = await deepgram.listen.prerecorded.transcribeUrl(
  { url: 'https://example.com/meeting.mp3' },
  {
    model: 'nova-2',
    smart_format: true,      // Add punctuation and capitalization
    diarize: true,           // Identify different speakers
    paragraphs: true,        // Group sentences into paragraphs
    language: 'en',
  }
);

if (error) throw new Error(error.message);

const transcript = result.results.channels[0]?.alternatives[0]?.transcript;
console.log('Transcript:', transcript);

// Speaker-labeled output
for (const word of result.results.channels[0]?.alternatives[0]?.words ?? []) {
  console.log(`[Speaker ${word.speaker}] ${word.word}`);
}
